CREATE TYPE "MembershipRole" AS ENUM ('OPERATOR','APPROVER','VIEWER');
CREATE TYPE "MembershipStatus" AS ENUM ('ACTIVE','SUSPENDED');
CREATE TYPE "ShipmentRequestStatus" AS ENUM ('NEEDS_REVIEW','APPROVED');
CREATE TYPE "IssueType" AS ENUM ('MISSING','CONFLICTING','UNCERTAIN','INVALID','UNSUPPORTED');
CREATE TYPE "ApprovalStatus" AS ENUM ('ACCEPTED'); CREATE TYPE "LoadStatus" AS ENUM ('DRAFT');
CREATE TYPE "StopType" AS ENUM ('PICKUP','DELIVERY'); CREATE TYPE "ActorType" AS ENUM ('USER','SYSTEM');
CREATE TYPE "IdempotencyStatus" AS ENUM ('IN_PROGRESS','COMPLETED');
CREATE TABLE organizations (id UUID PRIMARY KEY, slug TEXT UNIQUE NOT NULL, name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE users (id UUID PRIMARY KEY, email TEXT UNIQUE NOT NULL, name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE organization_memberships (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id), user_id UUID NOT NULL REFERENCES users(id), role "MembershipRole" NOT NULL, status "MembershipStatus" NOT NULL DEFAULT 'ACTIVE', UNIQUE(organization_id,user_id));
CREATE TABLE customers (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(organization_id,id), UNIQUE(organization_id,name));
CREATE TABLE shipment_requests (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id), status "ShipmentRequestStatus" NOT NULL DEFAULT 'NEEDS_REVIEW', current_revision_number INT NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(organization_id,id));
CREATE TABLE shipment_request_revisions (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id), shipment_request_id UUID NOT NULL, revision_number INT NOT NULL, original_text TEXT NOT NULL, structured_data JSONB NOT NULL, extraction_metadata JSONB NOT NULL, validation_results JSONB NOT NULL, created_by_id UUID NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(organization_id,id), UNIQUE(shipment_request_id,revision_number), FOREIGN KEY(organization_id,shipment_request_id) REFERENCES shipment_requests(organization_id,id));
CREATE TABLE shipment_issues (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id), shipment_request_id UUID NOT NULL, revision_id UUID NOT NULL, type "IssueType" NOT NULL, field TEXT NOT NULL, message TEXT NOT NULL, source_reference TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), FOREIGN KEY(organization_id,shipment_request_id) REFERENCES shipment_requests(organization_id,id), FOREIGN KEY(organization_id,revision_id) REFERENCES shipment_request_revisions(organization_id,id));
CREATE TABLE approval_requests (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id), shipment_request_id UUID NOT NULL, revision_id UUID UNIQUE NOT NULL, approved_by_id UUID NOT NULL REFERENCES users(id), status "ApprovalStatus" NOT NULL DEFAULT 'ACCEPTED', decision_reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(organization_id,id), UNIQUE(organization_id,revision_id), FOREIGN KEY(organization_id,shipment_request_id) REFERENCES shipment_requests(organization_id,id), FOREIGN KEY(organization_id,revision_id) REFERENCES shipment_request_revisions(organization_id,id));
CREATE TABLE loads (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id), shipment_request_id UUID UNIQUE NOT NULL, approved_revision_id UUID UNIQUE NOT NULL, customer_id UUID NOT NULL, load_number TEXT NOT NULL, status "LoadStatus" NOT NULL DEFAULT 'DRAFT', commodity TEXT NOT NULL, weight_pounds INT NOT NULL CHECK(weight_pounds > 0 AND weight_pounds <= 80000), equipment_type TEXT NOT NULL CHECK(equipment_type='DRY_VAN'), pickup_date DATE NOT NULL, delivery_date DATE NOT NULL CHECK(delivery_date >= pickup_date), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(organization_id,id), UNIQUE(organization_id,shipment_request_id), UNIQUE(organization_id,approved_revision_id), UNIQUE(organization_id,load_number), FOREIGN KEY(organization_id,shipment_request_id) REFERENCES shipment_requests(organization_id,id), FOREIGN KEY(organization_id,approved_revision_id) REFERENCES shipment_request_revisions(organization_id,id), FOREIGN KEY(organization_id,customer_id) REFERENCES customers(organization_id,id));
CREATE TABLE load_stops (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id), load_id UUID NOT NULL, sequence INT NOT NULL, type "StopType" NOT NULL, facility_name TEXT NOT NULL, city TEXT NOT NULL, state TEXT NOT NULL CHECK(state ~ '^[A-Z]{2}$'), postal_code TEXT NOT NULL, appointment_start TIMESTAMPTZ, appointment_end TIMESTAMPTZ, instructions TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(load_id,sequence), CHECK(appointment_end IS NULL OR appointment_start IS NOT NULL), CHECK(appointment_end IS NULL OR appointment_end > appointment_start), FOREIGN KEY(organization_id,load_id) REFERENCES loads(organization_id,id));
CREATE TABLE load_status_history (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id), load_id UUID NOT NULL, to_status "LoadStatus" NOT NULL, actor_id UUID NOT NULL, reason TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), FOREIGN KEY(organization_id,load_id) REFERENCES loads(organization_id,id));
CREATE TABLE audit_events (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id), actor_type "ActorType" NOT NULL, actor_id UUID, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id UUID NOT NULL, before_state JSONB, after_state JSONB NOT NULL, metadata JSONB, correlation_id UUID NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX audit_events_timeline ON audit_events(organization_id,entity_type,entity_id,created_at);
CREATE TABLE idempotency_records (id UUID PRIMARY KEY, organization_id UUID NOT NULL REFERENCES organizations(id), command TEXT NOT NULL, key TEXT NOT NULL, request_hash TEXT NOT NULL, status "IdempotencyStatus" NOT NULL DEFAULT 'IN_PROGRESS', result_entity_id UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ, UNIQUE(organization_id,command,key));
ALTER TABLE shipment_issues ADD FOREIGN KEY(organization_id) REFERENCES organizations(id); ALTER TABLE shipment_request_revisions ADD FOREIGN KEY(organization_id) REFERENCES organizations(id); ALTER TABLE approval_requests ADD FOREIGN KEY(organization_id) REFERENCES organizations(id); ALTER TABLE loads ADD FOREIGN KEY(organization_id) REFERENCES organizations(id); ALTER TABLE load_stops ADD FOREIGN KEY(organization_id) REFERENCES organizations(id); ALTER TABLE load_status_history ADD FOREIGN KEY(organization_id) REFERENCES organizations(id); ALTER TABLE audit_events ADD FOREIGN KEY(organization_id) REFERENCES organizations(id); ALTER TABLE idempotency_records ADD FOREIGN KEY(organization_id) REFERENCES organizations(id);
CREATE FUNCTION reject_immutable_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION '% is append-only', TG_TABLE_NAME; END $$;
CREATE TRIGGER revisions_immutable BEFORE UPDATE OR DELETE ON shipment_request_revisions FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
CREATE TRIGGER status_history_immutable BEFORE UPDATE OR DELETE ON load_status_history FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
